/*Table structure for table `barbershops` */

DROP TABLE IF EXISTS `barbershops`;

CREATE TABLE `barbershops` (
  `barbershop_id` int(11) NOT NULL AUTO_INCREMENT,
  `barbershop_admin` int(11) NOT NULL,
  `barbershop_name` varchar(150) NOT NULL,
  `barbershop_phone` varchar(20) NOT NULL,
  `barbershop_code` varchar(50) NOT NULL,
  `barbershop_private_code` varchar(50) DEFAULT NULL,
  `barbershop_address` varchar(200) NOT NULL,
  `barbershop_description` varchar(500) DEFAULT NULL,
  `barbershop_cover_url` varchar(255) DEFAULT NULL,
  `barbershop_profile_url` varchar(255) DEFAULT NULL,
  `barbershop_tier` tinyint(4) NOT NULL DEFAULT 1,
  `barbershop_is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`barbershop_id`),
  UNIQUE KEY `uq_barbershop_code` (`barbershop_code`),
  UNIQUE KEY `uq_barbershop_private_code` (`barbershop_private_code`),
  KEY `fk_barbershop_admin` (`barbershop_admin`),
  CONSTRAINT `fk_barbershop_admin` FOREIGN KEY (`barbershop_admin`) REFERENCES `admins` (`admin_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

