/*Table structure for table `log` */

DROP TABLE IF EXISTS `log`;

CREATE TABLE `log` (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  `log_barbershop` int(11) NOT NULL,
  `log_user` varchar(36) NOT NULL,
  `log_action_code` int(11) NOT NULL,
  `log_description` varchar(255) DEFAULT NULL,
  `log_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`log_id`),
  KEY `fk_log_barbershop` (`log_barbershop`),
  KEY `fk_log_user` (`log_user`),
  KEY `fk_log_action_code` (`log_action_code`),
  CONSTRAINT `fk_log_action_code` FOREIGN KEY (`log_action_code`) REFERENCES `action_codes` (`action_code_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_log_barbershop` FOREIGN KEY (`log_barbershop`) REFERENCES `barbershops` (`barbershop_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_log_user` FOREIGN KEY (`log_user`) REFERENCES `users` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `log` */

/*Table structure for table `notification_preferences` */

DROP TABLE IF EXISTS `notification_preferences`;

CREATE TABLE `notification_preferences` (
  `np_id` int(11) NOT NULL AUTO_INCREMENT,
  `np_user` varchar(36) NOT NULL,
  `np_push` tinyint(1) NOT NULL DEFAULT 1,
  `np_email` tinyint(1) NOT NULL DEFAULT 1,
  `np_sms` tinyint(1) NOT NULL DEFAULT 0,
  `np_whatsapp` tinyint(1) NOT NULL DEFAULT 0,
  `np_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `np_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`np_id`),
  UNIQUE KEY `uq_np_user` (`np_user`),
  CONSTRAINT `fk_np_user` FOREIGN KEY (`np_user`) REFERENCES `users` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `notification_preferences` */

/*Table structure for table `notification_tokens` */

DROP TABLE IF EXISTS `notification_tokens`;

CREATE TABLE `notification_tokens` (
  `nt_id` int(11) NOT NULL AUTO_INCREMENT,
  `nt_user` varchar(36) NOT NULL,
  `nt_token` varchar(512) NOT NULL,
  `nt_device_type` enum('android','ios','web') NOT NULL,
  `nt_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `nt_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`nt_id`),
  UNIQUE KEY `uq_nt_token` (`nt_token`),
  KEY `idx_nt_user` (`nt_user`),
  CONSTRAINT `fk_nt_user` FOREIGN KEY (`nt_user`) REFERENCES `users` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

/*Data for the table `notification_tokens` */

/*Table structure for table `refresh_tokens` */

DROP TABLE IF EXISTS `refresh_tokens`;

CREATE TABLE `refresh_tokens` (
  `rt_id` int(11) NOT NULL AUTO_INCREMENT,
  `rt_user` varchar(36) NOT NULL,
  `rt_expires_at` datetime NOT NULL,
  `rt_token` varchar(512) NOT NULL,
  `rt_device` varchar(255) NOT NULL,
  `rt_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`rt_id`),
  UNIQUE KEY `uq_rt_user_device` (`rt_user`,`rt_device`),
  KEY `fk_rt_user` (`rt_user`),
  CONSTRAINT `fk_rt_user` FOREIGN KEY (`rt_user`) REFERENCES `users` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

