/*Table structure for table `reservations` */

DROP TABLE IF EXISTS `reservations`;

CREATE TABLE `reservations` (
  `reservation_id` int(11) NOT NULL AUTO_INCREMENT,
  `reservation_client` varchar(36) NOT NULL,
  `reservation_employee` int(11) NOT NULL,
  `reservation_service` int(11) NOT NULL,
  `reservation_barbershop` int(11) NOT NULL,
  `reservation_datetime` datetime NOT NULL,
  `reservation_start_slot` int(11) NOT NULL,
  `reservation_occupied_slots` int(11) NOT NULL,
  `reservation_status` int(11) NOT NULL,
  `reservation_created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`reservation_id`),
  UNIQUE KEY `uq_employee_slot` (`reservation_employee`,`reservation_datetime`,`reservation_start_slot`),
  KEY `fk_reservation_client` (`reservation_client`),
  KEY `fk_reservation_employee` (`reservation_employee`),
  KEY `fk_reservation_service` (`reservation_service`),
  KEY `fk_reservation_barbershop` (`reservation_barbershop`),
  KEY `fk_reservation_status` (`reservation_status`),
  CONSTRAINT `fk_reservation_barbershop` FOREIGN KEY (`reservation_barbershop`) REFERENCES `barbershops` (`barbershop_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_reservation_client` FOREIGN KEY (`reservation_client`) REFERENCES `users` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_reservation_employee` FOREIGN KEY (`reservation_employee`) REFERENCES `employees` (`employee_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_reservation_service` FOREIGN KEY (`reservation_service`) REFERENCES `services_by_barbershop` (`sxb_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_reservation_status` FOREIGN KEY (`reservation_status`) REFERENCES `status` (`status_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4776 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

